SELECT BEM.CODBEM,
	BEM.DESCRICAO,
	BEM.TEMPO,
	(CASE WHEN BEM.TIPOTEMPO = 'D' THEN 'DIA' WHEN BEM.TIPOTEMPO = 'M' THEN 'MÊS' ELSE 'ANO' END) AS TIPOTEMPO,
	BEM.LOCAL,
	(SELECT (CASE WHEN BEM.TIPOTEMPO = 'D' THEN MAX(CTR.DTPREV) + BEM.TEMPO WHEN BEM.TIPOTEMPO = 'M' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO) WHEN BEM.TIPOTEMPO = 'A' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO*12) END) AS PROXIMAMANUTENCAO FROM AD_PRVCTR CTR	WHERE CTR.CODBEM = BEM.CODBEM) AS PROXIMAMANUTENCAO,
	(CASE WHEN ((SELECT (CASE WHEN BEM.TIPOTEMPO = 'D' THEN MAX(CTR.DTPREV) + BEM.TEMPO WHEN BEM.TIPOTEMPO = 'M' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO) WHEN BEM.TIPOTEMPO = 'A' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO*12) END) FROM AD_PRVCTR CTR WHERE CTR.CODBEM = BEM.CODBEM) - TRUNC(SYSDATE)) > 5 THEN '#63b108'
		WHEN ((SELECT (CASE WHEN BEM.TIPOTEMPO = 'D' THEN MAX(CTR.DTPREV) + BEM.TEMPO WHEN BEM.TIPOTEMPO = 'M' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO) WHEN BEM.TIPOTEMPO = 'A' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO*12) END) FROM AD_PRVCTR CTR WHERE CTR.CODBEM = BEM.CODBEM) - TRUNC(SYSDATE)) <= 5 THEN '#e9d90d'
		WHEN ((SELECT (CASE WHEN BEM.TIPOTEMPO = 'D' THEN MAX(CTR.DTPREV) + BEM.TEMPO WHEN BEM.TIPOTEMPO = 'M' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO) WHEN BEM.TIPOTEMPO = 'A' THEN ADD_MONTHS(MAX(CTR.DTPREV),BEM.TEMPO*12) END) FROM AD_PRVCTR CTR WHERE CTR.CODBEM = BEM.CODBEM) - TRUNC(SYSDATE)) <= 0 THEN '#f44336' END) AS BKCOLOR
FROM AD_ADCADBENS BEM
WHERE (BEM.CODBEM = :P_CODBEM OR :P_CODBEM IS NULL)
